macro_rules! deps {
    () => {
        NonZero!();
        ConstCtOption!();
        Limb!();
        Odd!();
        Invert!();
        Uint!();
        Int!();
        Word!();
        ConstChoice!();
    };
}

macro_rules! impl_99 {
    () => {
        deps!();
        impl < const LIMBS : usize > Int < LIMBS > { # [doc = " The value `0`."] pub const ZERO : Self = Self (Uint :: ZERO) ; # [doc = " The value `1`."] pub const ONE : Self = Self (Uint :: ONE) ; # [doc = " The value `-1`"] pub const MINUS_ONE : Self = Self :: FULL_MASK ; # [doc = " Smallest value this [`Int`] can express."] pub const MIN : Self = Self (Uint :: MAX . bitxor (& Uint :: MAX . shr (1u32))) ; # [doc = " Maximum value this [`Int`] can express."] pub const MAX : Self = Self (Uint :: MAX . shr (1u32)) ; # [doc = " Bit mask for the sign bit of this [`Int`]."] pub const SIGN_MASK : Self = Self :: MIN ; # [doc = " All-one bit mask."] pub const FULL_MASK : Self = Self (Uint :: MAX) ; # [doc = " Total size of the represented integer in bits."] pub const BITS : u32 = Uint :: < LIMBS > :: BITS ; # [doc = " Total size of the represented integer in bytes."] pub const BYTES : usize = Uint :: < LIMBS > :: BYTES ; # [doc = " The number of limbs used on this platform."] pub const LIMBS : usize = LIMBS ; # [doc = " Const-friendly [`Int`] constructor."] pub const fn new (limbs : [Limb ; LIMBS]) -> Self { Self (Uint :: new (limbs)) } # [doc = " Const-friendly [`Int`] constructor."] # [doc = ""] # [doc = " Reinterprets the bits of a value of type [`Uint`] as an [`Int`]."] # [doc = " For a proper conversion, see [`Int::new_from_abs_sign`];"] # [doc = " the public interface of this function is available at [`Uint::as_int`]."] pub (crate) const fn from_bits (value : Uint < LIMBS >) -> Self { Self (value) } # [doc = " Create an [`Int`] from an array of [`Word`]s (i.e. word-sized unsigned"] # [doc = " integers)."] # [inline] pub const fn from_words (arr : [Word ; LIMBS]) -> Self { Self (Uint :: from_words (arr)) } # [doc = " Create an array of [`Word`]s (i.e. word-sized unsigned integers) from"] # [doc = " an [`Int`]."] # [inline] pub const fn to_words (self) -> [Word ; LIMBS] { self . 0 . to_words () } # [doc = " Borrow the inner limbs as an array of [`Word`]s."] pub const fn as_words (& self) -> & [Word ; LIMBS] { self . 0 . as_words () } # [doc = " Borrow the inner limbs as a mutable array of [`Word`]s."] pub fn as_mut_words (& mut self) -> & mut [Word ; LIMBS] { self . 0 . as_mut_words () } # [doc = " Borrow the inner limbs as a mutable slice of [`Word`]s."] # [deprecated (since = "0.7.0" , note = "please use `as_mut_words` instead")] pub fn as_words_mut (& mut self) -> & mut [Word] { self . as_mut_words () } # [doc = " Borrow the limbs of this [`Int`]."] pub const fn as_limbs (& self) -> & [Limb ; LIMBS] { self . 0 . as_limbs () } # [doc = " Borrow the limbs of this [`Int`] mutably."] pub const fn as_mut_limbs (& mut self) -> & mut [Limb ; LIMBS] { self . 0 . as_mut_limbs () } # [doc = " Borrow the limbs of this [`Int`] mutably."] # [deprecated (since = "0.7.0" , note = "please use `as_mut_limbs` instead")] pub const fn as_limbs_mut (& mut self) -> & mut [Limb] { self . as_mut_limbs () } # [doc = " Convert this [`Int`] into its inner limbs."] pub const fn to_limbs (self) -> [Limb ; LIMBS] { self . 0 . to_limbs () } # [doc = " Convert to a [`NonZero<Int<LIMBS>>`]."] # [doc = ""] # [doc = " Returns some if the original value is non-zero, and false otherwise."] pub const fn to_nz (self) -> ConstCtOption < NonZero < Self > > { ConstCtOption :: new (NonZero (self) , self . 0 . is_nonzero ()) } # [doc = " Convert to a [`Odd<Int<LIMBS>>`]."] # [doc = ""] # [doc = " Returns some if the original value is odd, and false otherwise."] pub const fn to_odd (self) -> ConstCtOption < Odd < Self > > { ConstCtOption :: new (Odd (self) , self . 0 . is_odd ()) } # [doc = " Interpret the data in this object as a [`Uint`] instead."] # [doc = ""] # [doc = " Note: this is a casting operation. See"] # [doc = " - [`Self::try_into_uint`] for the checked equivalent, and"] # [doc = " - [`Self::abs`] to obtain the absolute value of `self`."] pub const fn as_uint (& self) -> & Uint < LIMBS > { & self . 0 } # [doc = " Get a [`Uint`] equivalent of this value; returns `None` if `self` is negative."] # [doc = ""] # [doc = " Note: this is a checked conversion operation. See"] # [doc = " - [`Self::as_uint`] for the unchecked equivalent, and"] # [doc = " - [`Self::abs`] to obtain the absolute value of `self`."] pub const fn try_into_uint (self) -> ConstCtOption < Uint < LIMBS > > { ConstCtOption :: new (self . 0 , self . is_negative () . not ()) } # [doc = " Whether this [`Int`] is equal to `Self::MIN`."] pub const fn is_min (& self) -> ConstChoice { Self :: eq (self , & Self :: MIN) } # [doc = " Whether this [`Int`] is equal to `Self::MAX`."] pub fn is_max (& self) -> ConstChoice { Self :: eq (self , & Self :: MAX) } # [doc = " Invert the most significant bit (msb) of this [`Int`]"] const fn invert_msb (& self) -> Self { Self (self . 0 . bitxor (& Self :: SIGN_MASK . 0)) } }
    };
}

impl_99!();